package gooo_workspace
namespace gooo_workspace

entity Text id "gooo://std/text"
entity Boolean id "gooo://std/boolean"
entity GrantImpact id "gooo://service-impact/decision/v1" fields {
    field before_match id "gooo://service-impact/before" type boolean required one
    field after_match id "gooo://service-impact/after" type boolean required one
    field change id "gooo://service-impact/change" type string required one
}
entity CheckedImpactDecision id "gooo://service-policy/checked-impact/decision/v1" fields {
    field domain_status id "gooo://service-policy/checked-impact/domain_status" type string required one
    field invalid_field id "gooo://service-policy/checked-impact/invalid_field" type string required one
    field before_match id "gooo://service-policy/checked-impact/before_match" type boolean required one
    field after_match id "gooo://service-policy/checked-impact/after_match" type boolean required one
    field change id "gooo://service-policy/checked-impact/change" type string required one
}
activity GoooPackage0ActivityMatchServicePattern(Text, Text, Text) -> Boolean id "gooo://agentmesh-prototype/match-service-pattern" computes "
if input0 == "" || input1 == "" || input2 == "" { return false }
if input0 == "*" { return true }
let split = -1
let offset = 0
for offset = 0; offset < 128; offset = offset + 1 {
 let end = offset + 3
 if end <= int64(len(input0)) {
  if input0[offset:end] == "://" { if split == -1 { split = offset } }
 }
}
if split < 0 { return false }
let nameStart = split + 3
let patternType = input0[0:split]
let patternName = input0[nameStart:int64(len(input0))]
if patternType != input1 || patternName == "" { return false }
if patternName == "*" { return true }
let patternLength = int64(len(patternName))
let requestLength = int64(len(input2))
if patternLength >= 2 {
 if patternName[0:2] == "*." {
  let suffix = patternName[1:patternLength]
  let suffixLength = int64(len(suffix))
  if requestLength < suffixLength { return false }
  let suffixStart = requestLength - suffixLength
  return input2[suffixStart:requestLength] == suffix
 }
 let tailStart = patternLength - 2
 if patternName[tailStart:patternLength] == ".*" {
  let prefixEnd = patternLength - 1
  let prefix = patternName[0:prefixEnd]
  if requestLength < prefixEnd { return false }
  return input2[0:prefixEnd] == prefix
 }
}
return input2 == patternName
"
activity GoooPackage1ActivityCompareServiceGrant(Text, Text, Text, Text) -> GrantImpact id "gooo://service-impact/compare" computes "
let before = GoooPackage0ActivityMatchServicePattern(input0, input2, input3)
let after = GoooPackage0ActivityMatchServicePattern(input1, input2, input3)
let change = "UNCHANGED_DENY"
if before {
 if after { change = "UNCHANGED_ALLOW" } else { change = "REVOKED" }
} else {
 if after { change = "WIDENED" }
}
return GrantImpact{before_match: before, after_match: after, change: change}
"
activity GoooPackage2ActivityValidateServiceType(Text) -> Boolean id "gooo://service-domain/type" computes "
let n = int64(len(input))
if n > 128 { return false }
if n == 0 { return true }
let first = int64(input[0])
if !((first >= 65 && first <= 90) || (first >= 97 && first <= 122)) { return false }
let offset = 0
for offset = 0; offset < 128; offset = offset + 1 {
 if offset < n {
  let b = int64(input[offset])
  let alpha = (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
  let digit = b >= 48 && b <= 57
  if !alpha && !digit && b != 43 && b != 45 && b != 46 { return false }
 }
}
return true
"
activity GoooPackage3ActivityValidateServiceName(Text) -> Boolean id "gooo://service-domain/name" computes "
let n = int64(len(input))
if n > 128 { return false }
if n == 0 { return true }
let previousDot = true
let offset = 0
for offset = 0; offset < 128; offset = offset + 1 {
 if offset < n {
  let b = int64(input[offset])
  if b == 46 {
   if previousDot { return false }
   previousDot = true
  } else {
   let alpha = (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
   let digit = b >= 48 && b <= 57
   if !alpha && !digit && b != 45 && b != 95 { return false }
   previousDot = false
  }
 }
}
return !previousDot
"
activity GoooPackage4ActivityValidateServicePattern(Text) -> Boolean id "gooo://service-domain/pattern" computes "
let n = int64(len(input))
if n > 128 { return false }
if input == "" || input == "*" { return true }
let split = -1
let offset = 0
for offset = 0; offset < 128; offset = offset + 1 {
 let end = offset + 3
 if end <= n {
  if input[offset:end] == "://" { if split == -1 { split = offset } }
 }
}
if split <= 0 { return false }
let typ = input[0:split]
if !GoooPackage2ActivityValidateServiceType(typ) { return false }
let start = split + 3
let part = input[start:n]
let size = int64(len(part))
if size == 0 { return false }
if part == "*" { return true }
if size >= 2 {
 if part[0:2] == "*." { part = part[2:size] } else {
  let tail = size - 2
  if part[tail:size] == ".*" { part = part[0:tail] }
 }
}
if part == "" { return false }
return GoooPackage3ActivityValidateServiceName(part)
"
activity GoooPackage5ActivityCompareServiceGrantChecked(Text, Text, Text, Text) -> CheckedImpactDecision id "gooo://service-policy/checked-impact/evaluate/v1" computes "
if !GoooPackage4ActivityValidateServicePattern(input0) { return CheckedImpactDecision{domain_status: "INVALID_INPUT", invalid_field: "before", before_match: false, after_match: false, change: "INVALID_INPUT"} }
if !GoooPackage4ActivityValidateServicePattern(input1) { return CheckedImpactDecision{domain_status: "INVALID_INPUT", invalid_field: "after", before_match: false, after_match: false, change: "INVALID_INPUT"} }
if !GoooPackage2ActivityValidateServiceType(input2) { return CheckedImpactDecision{domain_status: "INVALID_INPUT", invalid_field: "req_type", before_match: false, after_match: false, change: "INVALID_INPUT"} }
if !GoooPackage3ActivityValidateServiceName(input3) { return CheckedImpactDecision{domain_status: "INVALID_INPUT", invalid_field: "req_name", before_match: false, after_match: false, change: "INVALID_INPUT"} }
let result = GoooPackage1ActivityCompareServiceGrant(input0, input1, input2, input3)
return CheckedImpactDecision{domain_status: "VALID_INPUT", invalid_field: "", before_match: result.before_match, after_match: result.after_match, change: result.change}
"
